-- HANA-SOURCE: cl/bcs/tesoreria/sql/GestionDeDepositos_UpdateComprobanteFormaDePago.sql
-- H2 rewrite: DD/TFP joins -> EXISTS and scalar subquery; CURRENT_UTCTIMESTAMP 'HH24:MI:SS.FF7' = fixed clock + 7 zero decimals. Params: FechaMovimiento, Id, Entidad.
UPDATE "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP SET "Depositado" = 'S', "FechaAfectaSaldo" = CASE WHEN INSTR((SELECT MAX(TFP."AfectaSaldoEnEstado") FROM "BSCL.Tesoreria.BD::TES.TipoMovimientoMedioDePago" AS TFP WHERE TFP."IdTipoMovimiento" = CFP."IdTipoMovimiento" AND TFP."IdMedioDePago" = CFP."IdMedioDePago"), 'LIQ') > 0 AND COALESCE(CFP."IdCuentaBancariaCorredora", 0) > 0 AND COALESCE(CFP."FechaAfectaSaldo", '0001-01-01') = '0001-01-01' THEN CAST(CAST(DATEADD('DAY', CFP."DiasRetencion", PARSEDATETIME(:FechaMovimiento, 'yyyy-MM-dd')) AS DATE) || ' ' || FORMATDATETIME(HANA_UTCNOW(), 'HH:mm:ss') || '.0000000' AS TIMESTAMP) ELSE CFP."FechaAfectaSaldo" END WHERE EXISTS (SELECT 1 FROM "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD INNER JOIN "BSCL.Tesoreria.BD::TES.TipoMovimientoMedioDePago" AS TFP ON TFP."IdTipoMovimiento" = CFP."IdTipoMovimiento" AND TFP."IdMedioDePago" = CFP."IdMedioDePago" WHERE CFP."IdComprobanteFormaDePago" = DD."IdComprobanteFormaDePago" AND :Id = CASE WHEN (:Entidad = 'TES.Deposito') THEN DD."IdDeposito" ELSE DD."IdDepositoDetalle" END AND DD."IdEstado" = 'LIQ') AND CFP."IdEstado" = 'LIQ'
